        .0
        .transcript_log
        .lock()
        .await
        .add(AGENT, &req.text, route)
    {
        emit_json(&state, json!({"type":"spoken", "entry":entry}));
    }

    let delivered = state.0.events.receiver_count() > 0;
    if let Some(permit) = speech_permit {
        permit.send(spoken);
    }

    Json(delivery_response(delivered)).into_response()
}
