  </head>
  <body>
    <div id="shell">
      <!-- Left half, hidden until an agent draws something. Sits before the column
       so that on a narrow screen it stacks on top rather than below the fold. -->
      <section id="stage">
        <p id="stageTitle">Diagram</p>
        <div id="stageCanvas"></div>
        <p id="stageZoom">
          <button type="button" data-zoom="-">&minus;</button>
          <button type="button" data-zoom="+">+</button>
          <!-- Two answers, one button: a wide diagram wants containing and a tall
           one wants the width, so pressing it again asks for the other. -->
          <button
            type="button"
            data-zoom="0"
            title="Fit the whole diagram; press again to fill the width"
          >
            fit
          </button>
          <span id="stageZoomLabel">100%</span>
          <!-- Its own attribute rather than a fourth data-zoom value: this does not
           zoom anything, and the zoom handler should not have to know it. -->
          <button
            type="button"
            data-stage="theater"
            title="Give the diagram the whole screen (T)"
          >
            theater
          </button>
        </p>
        <p id="stageNotes"></p>
        <p id="stageError"></p>
      </section>

      <main id="column">
        <h1>Switchboard</h1>
        <p class="sub">
          Tap to talk. The operator connects you; the project agent hands you
          back.
        </p>

        <div id="line">
          <span class="who" id="who">—</span>
          <span class="model" id="model"></span>
          <div id="legControls">
            <select
              id="routeSelect"
              title="Connect straight to a project, without asking the operator"
            >
              <option value="operator">Operator</option>
            </select>
            <select
              id="modelSelect"
              title="Model for this leg and the ones after it"
            ></select>
            <select
              id="thinkingSelect"
              title="Thinking level for this leg and the ones after it"
            ></select>
            <button
              id="hangupBtn"
              class="hidden"
              title="Drop this leg and go back to the operator"
            >
              Hang up
            </button>
          </div>
        </div>

        <div id="controls">
          <button id="talkBtn">Talk</button>
          <button id="cancelBtn" class="hidden" title="Discard">
            &#9632; Discard
          </button>
          <button id="sendBtn" class="hidden" title="Send">
            &#10148; Send
          </button>
        </div>
        <div id="status">Connecting...</div>
        <button
          id="retryBtn"
          class="hidden"
          type="button"
          title="Replace a stale connection and retransmit every unacknowledged clip"
        >
          Retry now / Force send
        </button>

        <!-- What the leg is doing right now. Hidden between turns: an empty
         panel on an idle line is furniture, not information. -->
        <div id="activity" class="hidden">
          <div id="activityHead">
            <span id="activitySpinner"></span>
            <span id="activityWho">working</span>
            <span id="activityClock">0s</span>
          </div>
          <ul id="activityList"></ul>
        </div>

        <p class="label">Transcript</p>
        <div class="box" id="log"></div>

        <audio id="player" controls></audio>
      </main>
    </div>

    <!-- Outside #shell on purpose. #stage is hidden without a diagram and #column
     is hidden in theater mode, so the one control that has to survive both of
     those states cannot live inside either of them. -->
    <button
      id="theaterExit"
      type="button"
      title="Bring the call back (T or Escape)"
      aria-label="Leave theater mode"
    >
      &#10005;
    </button>

    <!-- Kept separate from the main script because it needs to be a module, and
     because a CDN that fails to load must cost the page its diagrams and
     nothing else. window.renderDiagram stays undefined and the caller still
     has a working phone. -->
    <script type="module" src="/diagram.js"></script>

    <script type="module" src="/app.js"></script>
  </body>
</html>

