        assert_eq!(
            header(json!({"type":"clip", "id":"a", "generation":-1})),
            Some(("a".into(), String::new(), None))
        );
        assert_eq!(
            header(json!({"type":"clip", "id":"a", "generation":"7"})),
            Some(("a".into(), String::new(), None))
        );

